const llegada = Date.now();
const tema = /^telemetria\/([0-9A-F]{12})\/lecturas$/.exec(msg.topic);
if (!tema) {
    node.warn(`Tema no válido: ${msg.topic}`);
    return null;
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (error) {
    node.warn(`JSON mal formado en ${msg.topic}`);
    return null;
}
if (datos === null || typeof datos !== 'object' || Array.isArray(datos)) {
    node.warn(`La trama de ${msg.topic} no es un objeto JSON`);
    return null;
}
if (typeof datos.mac !== 'string') {
    node.warn(`La trama de ${msg.topic} no trae la MAC`);
    return null;
}
const mac = datos.mac.toUpperCase();
if (!/^([0-9A-F]{2}:){5}[0-9A-F]{2}$/.test(mac)) {
    node.warn(`MAC no válida en ${msg.topic}: ${datos.mac}`);
    return null;
}
if (mac.replace(/:/g, '') !== tema[1]) {
    node.warn(`La MAC ${mac} no coincide con el tema ${msg.topic}`);
    return null;
}
const decimal = (valor, min, max) =>
    typeof valor === 'number' && Number.isFinite(valor) && valor >= min && valor <= max ? valor : null;
const entero = (valor, min, max) => (Number.isInteger(valor) && valor >= min && valor <= max ? valor : null);
const lectura = {
    ts: entero(datos.ts, 1700000000000, 4102444800000),
    uptime: entero(datos.uptime, 0, 2147483647),
    temperatura: decimal(datos.temperatura, -40, 85),
    humedad: decimal(datos.humedad, 0, 100),
    presion: decimal(datos.presion, 300, 1100),
    mq135_v: decimal(datos.mq135_v, 0.05, 5),
    rssi: entero(datos.rssi, -127, 0),
    fw: typeof datos.fw === 'string' && datos.fw.length > 0 && datos.fw.length <= 32 ? datos.fw : null,
};
const invalidos = Object.keys(lectura).filter(
    (campo) => lectura[campo] === null && datos[campo] !== null && datos[campo] !== undefined,
);
if (invalidos.length > 0) {
    node.warn(`Campos no válidos de ${mac}, se guardan como nulos: ${invalidos.join(', ')}`);
}
msg.llegada = llegada;
msg.mac = mac;
msg.lectura = lectura;
msg.query = `SELECT d.id, d.estado, d.cliente_id, d.ubicacion_id, d.mq135_r0_kohm, u.cliente_id AS cliente_ubicacion
FROM dispositivos d
LEFT JOIN ubicaciones u ON u.id = d.ubicacion_id
WHERE d.mac_address = $1`;
msg.params = [mac];
return msg;

const disp = msg.payload[0];
if (!disp) {
    node.warn(`Monitor no registrado: ${msg.mac}`);
    return null;
}
if (disp.estado !== 'en_uso') {
    node.warn(`Monitor ${msg.mac} en estado ${disp.estado}: no se guardan sus lecturas`);
    return null;
}
if (disp.ubicacion_id === null) {
    node.warn(`Monitor ${msg.mac} en uso sin ubicación asignada`);
    return null;
}
if (disp.cliente_id !== disp.cliente_ubicacion) {
    node.warn(`La ubicación ${disp.ubicacion_id} no pertenece al cliente del monitor ${msg.mac}`);
    return null;
}
const l = msg.lectura;
const latencia = l.ts !== null && Math.abs(msg.llegada - l.ts) <= 10000 ? msg.llegada - l.ts : null;
const RL_EF = (1 * 30) / (1 + 30);
const r0 = disp.mq135_r0_kohm === null ? null : Number(disp.mq135_r0_kohm);
let rsR0 = null;
let nivel = null;
if (l.mq135_v !== null && l.mq135_v < 5 && r0 > 0) {
    const razon = Math.round(((RL_EF * (5 - l.mq135_v)) / l.mq135_v / r0) * 1000) / 1000;
    if (razon <= 999.999) {
        rsR0 = razon;
        nivel = razon >= 0.8 ? 'bueno' : razon >= 0.5 ? 'moderado' : 'malo';
    } else {
        node.warn(`Rs/R0 de ${msg.mac} fuera de rango (${razon}): revisar el R0 del monitor`);
    }
}
msg.calculado = { latencia, rsR0, nivel };
msg.query = `WITH monitor AS (
  UPDATE dispositivos
  SET ultima_lectura_en = GREATEST(ultima_lectura_en, to_timestamp($3 / 1000.0)),
      ultimo_rssi = CASE WHEN ultima_lectura_en > to_timestamp($3 / 1000.0) THEN ultimo_rssi
        ELSE COALESCE($13::smallint, ultimo_rssi) END,
      ultimo_uptime_s = CASE WHEN ultima_lectura_en > to_timestamp($3 / 1000.0) THEN ultimo_uptime_s
        ELSE COALESCE($12::integer, ultimo_uptime_s) END,
      fw = CASE WHEN ultima_lectura_en > to_timestamp($3 / 1000.0) THEN fw
        ELSE COALESCE($14::text, fw) END
  WHERE id = $1 AND estado = 'en_uso' AND ubicacion_id = $2
  RETURNING id, ubicacion_id
)
INSERT INTO lecturas (dispositivo_id, ubicacion_id, fecha_hora, ts_dispositivo, latencia_ms,
  temperatura, humedad, presion, mq135_v, rs_r0, nivel_aire, uptime_s)
SELECT id, ubicacion_id, to_timestamp($3 / 1000.0), to_timestamp($4 / 1000.0), $5::integer,
  $6::numeric, $7::numeric, $8::numeric, $9::numeric, $10::numeric, $11::text, $12::integer
FROM monitor
RETURNING id, dispositivo_id, ubicacion_id, fecha_hora`;
msg.params = [disp.id, disp.ubicacion_id, msg.llegada, l.ts, latencia, l.temperatura, l.humedad, l.presion,
    l.mq135_v, rsR0, nivel, l.uptime, l.rssi, l.fw];
return msg;

const fila = msg.payload[0];
if (!fila) {
    node.warn(`El monitor ${msg.mac} cambió de estado o de ubicación antes de guardar la lectura`);
    return null;
}
const l = msg.lectura;
msg.lecturaId = Number(fila.id);
msg.payload = {
    tipo: 'lectura',
    ubicacionId: fila.ubicacion_id,
    dispositivoId: fila.dispositivo_id,
    fecha: new Date(fila.fecha_hora).toISOString(),
    temperatura: l.temperatura,
    humedad: l.humedad,
    presion: l.presion,
    rsR0: msg.calculado.rsR0,
    nivelAire: msg.calculado.nivel,
};
delete msg.query;
delete msg.params;
delete msg.pgsql;
return msg;
